-- Test fixture matching previously verified production columns; no production schema change.
create table companies(id text primary key,name text not null unique,overview text not null,subsector text not null,geography text not null,website text,is_sample boolean not null default false,created_at timestamptz default now());
create table sources(id text primary key,activity_id text,type text not null,url text,gmail_message_id text,sender text,subject text,received_date date,snippet text,title text not null,created_at timestamptz default now());
create table activities(id text primary key,date_announced date not null,company_id text not null references companies(id),counterparty text not null,activity_type text not null,subsector text not null,deal_value_usd numeric,geography text not null,description text not null,source_id text references sources(id),source_url text,source_reference text,source_type text not null,confidence text not null,review_status text not null default 'pending review',last_updated date not null,is_sample boolean not null default false,entered_by text,entered_at timestamptz,approved_by text,approved_at timestamptz,merged_from_candidate_ids text[],additional_sources jsonb);
create table review_queue_items(id text primary key,candidate_company text not null,candidate_counterparty text not null,candidate_date date not null,activity_type text not null,subsector text not null,deal_value_usd numeric,geography text not null,description text not null,source_type text not null,source_url text,gmail_message_id text,sender text,subject text,received_date date,snippet text not null,extracted_text text not null,confidence text not null,status text not null default 'pending',duplicate_of_activity_id text,created_at timestamptz default now(),intelligence_action text,intelligence_score integer,intelligence_evidence jsonb,intelligence_cautions jsonb,llm_model text,llm_status text);
create table data_exclusions(id text primary key,target_type text,target_id text,company_id text,restored_at timestamptz);